336	\subsection{F3: Unexposed Temporal Embedding Suppresses Value Drift}
337	\label{sec:f3}
338	
339	\begin{figure}[t]
340	\centering
341	\includegraphics[width=\columnwidth]{figures/paper/fig3_factorial_grid.pdf}
